import{_ as n,o as s,c as l,a2 as e}from"./chunks/framework.XXezeKOl.js";const d=JSON.parse('{"title":"Toolformer","description":"精读 Toolformer：语言模型如何通过自监督的方式学会自己决定何时调用工具、调用哪个工具、传什么参数。","frontmatter":{"title":"Toolformer","description":"精读 Toolformer：语言模型如何通过自监督的方式学会自己决定何时调用工具、调用哪个工具、传什么参数。"},"headers":[],"relativePath":"papers/toolformer.md","filePath":"papers/toolformer.md","lastUpdated":null}'),r={name:"papers/toolformer.md"};function o(i,a,p,t,c,u){return s(),l("div",null,[...a[0]||(a[0]=[e(`<h1 id="toolformer" tabindex="-1">Toolformer <a class="header-anchor" href="#toolformer" aria-label="Permalink to &quot;Toolformer&quot;">​</a></h1><h2 id="论文信息" tabindex="-1">论文信息 <a class="header-anchor" href="#论文信息" aria-label="Permalink to &quot;论文信息&quot;">​</a></h2><ul><li>标题：Toolformer: Language Models Can Teach Themselves to Use Tools</li><li>作者：Timo Schick、Jane Dwivedi-Yu、Roberto Dessì、Roberta Raileanu、Maria Lomeli、Luke Zettlemoyer、Nicola Cancedda、Thomas Scialom（Meta AI Research 等）</li><li>年份：2023（NeurIPS 2023）</li><li>链接：<a href="https://arxiv.org/abs/2302.04761" target="_blank" rel="noreferrer">arXiv:2302.04761</a></li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p>让模型自己在文本中插入候选的 API 调用，只保留&quot;调用结果确实有助于预测后文&quot;的那些，再用这些数据微调模型，模型就学会了自主决定何时、如何使用工具。</p><h2 id="要解决的问题" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h2><p>大模型在很多任务上能力很强，却在一些&quot;简单&quot;的事情上出错：算术计算、查询最新事实、知道今天是几号、低资源语言翻译。这些恰好是外部工具（计算器、搜索引擎、日历、翻译系统）擅长的。</p><p>当时让模型使用工具的方法有两类问题：</p><ul><li>依赖大量人工标注的工具使用数据，成本高。</li><li>只针对特定任务设计，模型不能自己判断&quot;这里需不需要用工具&quot;。</li></ul><p>作者希望找到一种方法，让模型以自监督的方式学会通用的工具使用能力，同时不损害它原本的语言建模能力。</p><h2 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><p>API 调用被表示成插在普通文本中的特殊片段，格式类似 <code>[Calculator(400 / 1400) → 0.29]</code>。整个数据构造流程分三步：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 普通文本语料</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>     ▼</span></span>
<span class="line"><span> ┌──────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span> │ 1. 采样：用少量示例提示模型，在文本中可能需要工具的位置       │</span></span>
<span class="line"><span> │    生成候选 API 调用，例如 [QA(&quot;谁创立了某公司?&quot;)]          │</span></span>
<span class="line"><span> └──────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>     ▼</span></span>
<span class="line"><span> ┌──────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span> │ 2. 执行：真正调用工具，拿到返回结果                          │</span></span>
<span class="line"><span> └──────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>     ▼</span></span>
<span class="line"><span> ┌──────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span> │ 3. 过滤：比较&quot;插入调用和结果&quot;前后，模型预测后续文本的损失     │</span></span>
<span class="line"><span> │    只有损失明显降低（即结果真的有用）的调用才被保留           │</span></span>
<span class="line"><span> └──────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>     ▼</span></span>
<span class="line"><span> 带有 API 调用的增强语料 ──▶ 微调原模型 ──▶ Toolformer</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br></div></div><p>推理时，模型正常生成文本；当它生成 API 调用的标记时，程序暂停生成、执行工具、把结果插回文本，再让模型继续。</p><p>论文使用的工具包括：问答系统、计算器、Wikipedia 搜索、机器翻译和日历。基座模型是一个约 67 亿参数的 GPT-J。</p><h2 id="关键实验结论" tabindex="-1">关键实验结论 <a class="header-anchor" href="#关键实验结论" aria-label="Permalink to &quot;关键实验结论&quot;">​</a></h2><ul><li><strong>小模型配合工具可以在多个零样本任务上超过大得多的模型。</strong> 经过训练的 Toolformer 在事实问答、数学计算、时间相关问题等任务上，表现超过了不使用工具的更大规模模型。</li><li><strong>模型学会了&quot;按需&quot;调用。</strong> 在需要计算的地方调用计算器，在需要事实的地方调用问答或搜索，在无关的地方不调用。</li><li><strong>语言建模能力没有明显下降。</strong> 在不允许调用工具时，模型的困惑度与原模型相近。</li><li><strong>工具使用能力与模型规模有关。</strong> 较小的模型很难从工具中获益，模型达到一定规模后才学会有效利用工具。</li></ul><h2 id="对-agent-开发的启发" tabindex="-1">对 Agent 开发的启发 <a class="header-anchor" href="#对-agent-开发的启发" aria-label="Permalink to &quot;对 Agent 开发的启发&quot;">​</a></h2><ul><li><strong>工具调用不是外挂，而是可以被训练进模型的能力。</strong> 今天主流模型原生支持 Tool Calling，背后正是这类研究的延续。作为应用开发者，你通常不需要自己训练，但要理解模型&quot;何时调用工具&quot;是一种学到的判断，会出错。</li><li><strong>&quot;有用&quot;是选择工具调用的标准。</strong> Toolformer 用&quot;能否降低后文预测损失&quot;来判断调用是否有价值。在 Agent 设计中，对应的问题是：这个工具返回的信息是否真的帮助完成任务？无用的工具调用只会浪费上下文和成本。</li><li><strong>工具返回要简洁。</strong> 论文中工具结果是被直接插入文本的短片段，这提醒我们工具返回应当精炼、与任务相关，而不是把整个页面塞给模型。</li><li><strong>把模型不擅长的事交给确定性工具。</strong> 计算、日期、精确查询这类任务，给模型一个工具比在提示词里反复强调&quot;请仔细计算&quot;可靠得多。</li></ul><h2 id="局限性" tabindex="-1">局限性 <a class="header-anchor" href="#局限性" aria-label="Permalink to &quot;局限性&quot;">​</a></h2><ul><li>工具不能链式使用：一个工具的输出不能作为另一个工具的输入，因为每个工具的训练数据是独立生成的。</li><li>不支持交互式使用：模型不能根据工具返回结果追问或调整调用，比如搜索结果不理想时重新搜索。</li><li>对提示词措辞敏感，判断是否调用工具时有时不稳定。</li><li>数据构造需要在大量文本上采样和执行工具，部分工具的有效样本很少，效率不高。</li><li>没有考虑调用工具的成本，模型不知道某个工具&quot;贵&quot;或&quot;慢&quot;。</li></ul><p>这些局限正是后来 <a href="/papers/react">ReAct</a> 式的交互循环和原生 Tool Calling 接口所弥补的。</p><h2 id="相关文章" tabindex="-1">相关文章 <a class="header-anchor" href="#相关文章" aria-label="Permalink to &quot;相关文章&quot;">​</a></h2><ul><li><a href="/guide/05-tool-calling/concept">工具调用原理</a></li><li><a href="/guide/05-tool-calling/tool-design">工具设计原则</a></li><li><a href="/guide/05-tool-calling/first-tool">实现第一个工具</a></li><li><a href="/guide/00-intro/capabilities">Agent 的能力边界与适用场景</a></li></ul>`,24)])])}const h=n(r,[["render",o]]);export{d as __pageData,h as default};
